\set ON_ERROR_STOP on
do $$ begin if current_database()<>'chibasko_distribution_test' then raise exception 'Disposable database required'; end if; end $$;
create table public.profiles(id uuid primary key references auth.users(id),username text);
grant select on public.profiles to service_role;
insert into public.profiles select id,'Player' from auth.users;
\ir ../supabase/migrations/20261018000200_multiplayer_lobbies.sql
set role anon;
select public.distribution_expect_failure('select * from public.multiplayer_lobbies');
select public.distribution_expect_failure('select public.distribution_multiplayer_snapshot(null,gen_random_uuid())');
reset role;
set role authenticated;
select public.distribution_expect_failure('select * from public.multiplayer_lobby_members');
select public.distribution_expect_failure('insert into public.multiplayer_lobbies default values');
select public.distribution_expect_failure('select * from public.multiplayer_lobby_rounds');
reset role;
set role service_role;
