do $$ declare a uuid:='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'; b uuid:='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'; c uuid:='cccccccc-cccc-4ccc-8ccc-cccccccccccc';
 g uuid:='23232323-2323-4323-8323-232323232323'; l uuid:=gen_random_uuid(); x jsonb; sid text; old_sid text; begin
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_create(null,%L,''public'',gen_random_uuid())',g),'unauthorized');
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_create(%L,''11111111-1111-4111-8111-111111111111'',''public'',gen_random_uuid())',a),'unsupported_access');
 perform public.distribution_expect_failure(format('insert into public.multiplayer_lobbies(game_id,version_id,access,min_players,max_players,start_policy) values(%L,''33333333-3333-4333-8333-333333333333'',''public'',2,3,''manual'')',g));
 x:=public.distribution_multiplayer_create(a,g,'private',l);
 if x<>public.distribution_multiplayer_create(a,g,'private',l) then raise exception 'Create is not idempotent'; end if;
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_mutate(%L,%L,''join'')',b,l),'lobby_not_found');
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_lookup(%L,%L,''BAD'')',b,g),'lobby_not_found');
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_snapshot(%L,%L)',c,l),'lobby_not_found');
 x:=public.distribution_multiplayer_lookup(b,g,x->>'code');
 x:=public.distribution_multiplayer_mutate(b,l,'join');
 if jsonb_array_length(x->'members')<>2 then raise exception 'Private join failed'; end if;
 if public.distribution_multiplayer_list(a,g)::text like '%'||l||'%' then raise exception 'Private directory leak'; end if;
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_start(%L,%L)',b,l),'forbidden');
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_start(%L,%L)',a,l),'not_ready');
 perform public.distribution_multiplayer_mutate(a,l,'ready',true);
 perform public.distribution_multiplayer_mutate(b,l,'ready',true);
 x:=public.distribution_multiplayer_start(a,l); sid:=x->>'onlineSessionReference';old_sid:=sid;
 if x->>'status'<>'starting' or (select count(*) from public.game_online_participants where session_id=sid)<>2 then raise exception 'Roster was not frozen'; end if;
 if public.distribution_multiplayer_start(a,l)->>'onlineSessionReference'<>sid then raise exception 'Duplicate START'; end if;
 if exists(select 1 from public.game_connection_tickets where session_id=sid) then raise exception 'Lobby issued ticket prematurely'; end if;
 if public.distribution_multiplayer_server_event(repeat('a',64),sid,'results')#>>'{error,code}'<>'online_session_unavailable' then raise exception 'Wrong deployment accepted'; end if;
 if public.distribution_multiplayer_server_event(repeat('f',64),sid,'results')#>>'{error,code}'<>'invalid_credential' then raise exception 'Invalid credential accepted'; end if;
 perform public.distribution_multiplayer_server_event(repeat('7',64),sid,'playing');
 perform public.distribution_multiplayer_server_event(repeat('7',64),sid,'results');
 perform public.distribution_multiplayer_server_event(repeat('7',64),sid,'results');
 perform public.distribution_multiplayer_mutate(a,l,'replay');
 if exists(select 1 from public.multiplayer_lobby_members where lobby_id=l and ready) then raise exception 'Replay retained readiness'; end if;
 perform public.distribution_multiplayer_mutate(a,l,'ready',true); perform public.distribution_multiplayer_mutate(b,l,'ready',true);
 sid:=public.distribution_multiplayer_start(a,l)->>'onlineSessionReference';
 if sid=old_sid or (select status from public.game_online_sessions where id=old_sid)<>'closed' then raise exception 'Replay reused a session'; end if;
 perform public.distribution_multiplayer_mutate(a,l,'leave');
 if (select leader_actor from public.multiplayer_lobbies where id=l)<>b then raise exception 'Leader transfer failed'; end if;
 if not exists(select 1 from public.game_online_participants where session_id=sid and actor_id=a and removed_at is not null) then raise exception 'Leave did not revoke admission'; end if;
 perform public.distribution_multiplayer_mutate(b,l,'leave');
 if (select status from public.multiplayer_lobbies where id=l)<>'closed' then raise exception 'Empty lobby remained open'; end if;
 update public.game_online_sessions set closed_at=clock_timestamp()-interval '2 days' where id=old_sid;
 perform public.distribution_cleanup_online();
 if not exists(select 1 from public.game_online_sessions where id=old_sid) then raise exception 'Round history was garbage collected'; end if;
 perform public.distribution_expect_failure(format('update public.multiplayer_lobbies set version_id=%L where id=%L','33333333-3333-4333-8333-333333333333',l));
 l:=gen_random_uuid();x:=public.distribution_multiplayer_create(a,g,'public',l);
 update public.multiplayer_lobbies set waiting_until=clock_timestamp()-interval '1 second' where id=l;
 perform public.artifact_expect_code(format('select public.distribution_multiplayer_mutate(%L,%L,''join'')',b,l),'lobby_expired');
 perform public.distribution_multiplayer_mutate(a,l,'leave');
 perform public.distribution_cleanup_multiplayer();perform public.distribution_cleanup_multiplayer();
 if (select status from public.multiplayer_lobbies where id=l)<>'closed' then raise exception 'Expiry cleanup failed'; end if;
 insert into public.multiplayer_game_policies values(g,'when_full');
 l:=gen_random_uuid();perform public.distribution_multiplayer_create(a,g,'public',l);
 perform public.distribution_multiplayer_mutate(b,l,'join');perform public.distribution_multiplayer_mutate(c,l,'join');
 perform public.distribution_multiplayer_mutate(a,l,'ready',true);perform public.distribution_multiplayer_mutate(b,l,'ready',true);
 x:=public.distribution_multiplayer_mutate(c,l,'ready',true);
 if x->>'status'<>'starting' then raise exception 'when_full did not start atomically'; end if;
 perform public.distribution_multiplayer_mutate(a,l,'leave');
 if (select status from public.multiplayer_lobbies where id=l)<>'results' then raise exception 'Roster change during START did not cancel'; end if;
 delete from public.multiplayer_game_policies where game_id=g;
end $$;
reset role;
